const input = $input.first().json;

if (!input || !input.data || input.data.length === 0) {
  throw new Error('❌ Нет данных от Facebook API');
}

console.log(`📊 Получено ${input.data.length} дней данных`);

const projectId = '64c94e87-630c-470e-8ab1-8f7c8c835efa';

function safeParse(value, decimals = 2) {
  const num = parseFloat(value || 0);
  return isNaN(num) ? 0 : parseFloat(num.toFixed(decimals));
}

function safeInt(value) {
  const num = parseInt(value || 0, 10);
  return isNaN(num) ? 0 : num;
}

function extractAction(actions, actionTypes) {
  if (!actions || !Array.isArray(actions)) return 0;

  for (const type of actionTypes) {
    const action = actions.find(a => a.action_type === type);
    if (action) {
      const val = safeInt(action.value);
      if (val > 0) console.log(`   ✅ ${type}: ${val}`);
      return val;
    }
  }
  return 0;
}

const results = input.data.map(fbData => {
  console.log(`\n📅 ${fbData.date_start}`);

  const leads = extractAction(fbData.actions, [
    'lead',
    'leadgen_grouped',
    'onsite_conversion.lead_grouped'
  ]);

  const conversations = extractAction(fbData.actions, [
    'onsite_conversion.messaging_conversation_started_7d',
    'onsite_conversion.messaging_first_reply',
    'onsite_conversion.messaging_conversation_started_1d'
  ]);

  const result = {
    project_id: projectId,
    date: fbData.date_start,
    spend: safeParse(fbData.spend, 2),
    impressions: safeInt(fbData.impressions),
    clicks: safeInt(fbData.clicks),
    reach: safeInt(fbData.reach),
    ctr: safeParse(fbData.ctr, 4),
    cpc: safeParse(fbData.cpc, 2),
    cpm: safeParse(fbData.cpm, 2),
    leads: leads,
    conversations: conversations,
    source: 'facebook_ads'
  };

  console.log(`   💰 spend=${result.spend}, 👁️ impressions=${result.impressions}, 📝 leads=${result.leads}, 💬 conversations=${result.conversations}`);

  return result;
});

console.log(`\n✅ Трансформировано: ${results.length} дней\n`);

return results.map(r => ({ json: r }));

const items = $input.all();

const totalDays = items.length;
const totalSpend = items.reduce((sum, item) => {
  const spend = item.json[0]?.spend || item.json?.spend || 0;
  return sum + spend;
}, 0);

const totalLeads = items.reduce((sum, item) => {
  const leads = item.json[0]?.leads || item.json?.leads || 0;
  return sum + leads;
}, 0);

const totalConversations = items.reduce((sum, item) => {
  const conversations = item.json[0]?.conversations || item.json?.conversations || 0;
  return sum + conversations;
}, 0);

const totalImpressions = items.reduce((sum, item) => {
  const impressions = item.json[0]?.impressions || item.json?.impressions || 0;
  return sum + impressions;
}, 0);

const totalClicks = items.reduce((sum, item) => {
  const clicks = item.json[0]?.clicks || item.json?.clicks || 0;
  return sum + clicks;
}, 0);

const result = {
  success: true,
  days: totalDays,
  spend: `${totalSpend.toFixed(2)} ₸`,
  impressions: totalImpressions.toLocaleString(),
  clicks: totalClicks.toLocaleString(),
  leads: totalLeads,
  conversations: totalConversations,
  cpl: totalLeads > 0 ? `${(totalSpend / totalLeads).toFixed(2)} ₸` : 'N/A',
  cpc: totalClicks > 0 ? `${(totalSpend / totalClicks).toFixed(2)} ₸` : 'N/A',
  message: `✅ ИМПОРТИРОВАНО ${totalDays} ДНЕЙ!`
};

console.log('\n\n🎉 ИМПОРТ ЗАВЕРШЕН! 🎉');
console.log('========================');
console.log(`📊 Дней: ${totalDays}`);
console.log(`💰 Расходы: ${result.spend}`);
console.log(`👁️  Показы: ${result.impressions}`);
console.log(`🖱️  Клики: ${result.clicks}`);
console.log(`📝 Лиды: ${totalLeads}`);
console.log(`💬 Переписки: ${totalConversations}`);
console.log(`📈 CPL: ${result.cpl}`);
console.log(`📈 CPC: ${result.cpc}`);
console.log('========================\n\n');

return { json: result };
